    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700;800&display=swap" rel="stylesheet">
    <style>
        :root { --ink:#173b67; --deep:#24558a; --blue:#2e73ae; --sky:#eef7fc; --gold:#d7a84e; --cream:#f7fafc; --white:#fff; --muted:#5d6e7d; }
        * { box-sizing:border-box; } html { scroll-behavior:smooth; }
        body { margin:0; color:var(--ink); background:var(--cream); font-family:'DM Sans',sans-serif; }
        a { color:inherit; text-decoration:none; }
        .topbar { padding:8px 6vw; display:flex; justify-content:space-between; color:#607384; background:#f7fbfe; border-bottom:1px solid #e5eef5; font-size:11px; letter-spacing:.06em; }
        .topbar span:last-child { color:var(--blue); font-weight:700; }
        header { position:relative; z-index:2; width:100%; min-height:82px; padding:14px 6vw; display:flex; align-items:center; justify-content:space-between; color:var(--ink); background:var(--white); border-bottom:1px solid #e1e9f0; box-shadow:0 2px 10px rgba(24,67,105,.08); }
        .brand { display:flex; align-items:center; gap:12px; font-weight:700; letter-spacing:.08em; font-size:13px; text-transform:uppercase; color:var(--ink); }
        .crest { width:48px; height:56px; display:block; flex:0 0 auto; } .crest img { width:100%; height:100%; display:block; object-fit:contain; }
