        .nav-login { padding:10px 13px; border:1px solid #cbdbe8; color:var(--ink); }
        .nav-cta { padding:11px 17px; color:var(--white)!important; background:var(--blue); opacity:1!important; }
        .hero { min-height:520px; display:flex; align-items:center; justify-content:center; position:relative; color:var(--white); text-align:center; background-position:center; background-size:cover; }
        .hero-content { width:min(800px,90vw); padding:84px 5vw; } .eyebrow,.section-kicker { color:#f2cd76; font-size:12px; letter-spacing:.25em; font-weight:700; text-transform:uppercase; }
        h1,h2,h3 { font-family:'Playfair Display',serif; margin:0; font-weight:700; } h1 { max-width:800px; margin:18px auto 22px; font-size:clamp(42px,6vw,76px); line-height:1.02; letter-spacing:.01em; text-transform:uppercase; text-shadow:0 2px 18px rgba(0,0,0,.22); }
        .hero p { max-width:600px; margin:0 auto; color:rgba(255,255,255,.94); font-size:17px; line-height:1.7; text-shadow:0 1px 8px rgba(0,0,0,.35); } .hero-actions { display:flex; justify-content:center; gap:15px; margin-top:30px; flex-wrap:wrap; }
        .button { display:inline-flex; align-items:center; gap:12px; padding:16px 21px; font-size:12px; font-weight:700; letter-spacing:.12em; text-transform:uppercase; transition:transform .2s ease,background .2s ease; }
        .button:hover { transform:translateY(-3px); } .button-primary { color:var(--white); background:var(--blue); } .button-ghost { border:1px solid rgba(255,255,255,.8); background:rgba(0,0,0,.08); }
        .button-ghost:hover { background:rgba(255,255,255,.12); } .hero-note { position:absolute; right:6vw; bottom:40px; display:flex; align-items:center; gap:13px; font-size:11px; letter-spacing:.14em; text-transform:uppercase; writing-mode:vertical-rl; transform:rotate(180deg); opacity:.8; }
        .hero-note:before { content:''; width:1px; height:55px; background:#f2cd76; } section { padding:88px 6vw; }
        .intro { display:grid; grid-template-columns:.8fr 1.2fr; gap:10vw; align-items:center; background:var(--white); } .section-kicker { margin-bottom:18px; color:var(--blue); font-size:11px; letter-spacing:.22em; }
        h2 { color:var(--ink); font-size:clamp(35px,4vw,58px); line-height:1.05; letter-spacing:-.025em; } .intro-copy p { margin:25px 0 0; color:var(--muted); font-size:17px; line-height:1.8; }
        .intro-aside { padding:20px 0 20px 35px; border-left:1px solid var(--gold); } .intro-aside p { margin:0; color:var(--blue); font:600 clamp(22px,3vw,34px)/1.35 'Playfair Display',serif; } .intro-aside small { display:block; margin-top:26px; color:#65757b; font-size:12px; letter-spacing:.14em; text-transform:uppercase; }
