        .level:before { content:''; position:absolute; inset:0; background:linear-gradient(0deg,rgba(7,30,39,.9),transparent 75%); } .level>* { position:relative; } .level:nth-child(1) { background-image:url('https://images.unsplash.com/photo-1503454537195-1dcabb73ffb9?auto=format&fit=crop&w=900&q=80'); } .level:nth-child(2) { background-image:url('https://images.unsplash.com/photo-1577896851231-70ef18881754?auto=format&fit=crop&w=900&q=80'); } .level:nth-child(3) { background-image:url('https://images.unsplash.com/photo-1529390079861-591de354faf5?auto=format&fit=crop&w=900&q=80'); }
        .level-number { color:#e8c47d; font-size:12px; letter-spacing:.18em; } .level h3 { margin:9px 0 11px; font-size:34px; } .level p { max-width:320px; margin:0; color:rgba(255,255,255,.78); font-size:14px; line-height:1.65; }
        .values { display:grid; grid-template-columns:1.1fr 1fr; gap:8vw; align-items:center; background:#fff; color:var(--ink); } .values h2 { color:var(--ink); } .values .section-kicker { color:var(--blue); } .values-copy p { color:var(--muted); line-height:1.8; }
        .value-list { display:grid; grid-template-columns:1fr 1fr; border-top:1px solid #dce8f0; } .value-item { padding:23px 10px 23px 0; border-bottom:1px solid #dce8f0; } .value-item:nth-child(odd) { margin-right:25px; } .value-item strong { display:block; margin-bottom:7px; color:var(--blue); font:24px 'Playfair Display',serif; } .value-item span { color:var(--muted); font-size:13px; }
        .news { background:#f7fafc; } .news-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:18px; } .news-card { padding:25px; background:#fff; border:1px solid #dce8f0; } .news-card small { color:var(--blue); font-size:11px; font-weight:700; letter-spacing:.1em; text-transform:uppercase; } .news-card h3 { margin:10px 0; color:var(--ink); font-size:24px; } .news-card p { margin:0; color:var(--muted); line-height:1.65; } .news-link { display:inline-block; margin-top:17px; color:var(--blue); font-size:12px; font-weight:700; text-transform:uppercase; }
        .gallery { background:var(--cream); } .gallery-grid { display:grid; grid-template-columns:1.3fr .8fr .8fr; grid-template-rows:210px 210px; gap:8px; } .gallery-grid div { background-position:center; background-size:cover; } .gallery-grid div:first-child { grid-row:span 2; background-image:url('https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1000&q=85'); } .gallery-grid div:nth-child(2) { background-image:url('https://images.unsplash.com/photo-1588072432836-e10032774350?auto=format&fit=crop&w=800&q=85'); } .gallery-grid div:nth-child(3) { background-image:url('https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=800&q=85'); } .gallery-grid div:nth-child(4) { background-image:url('https://images.unsplash.com/photo-1571260899304-425eee4c7efc?auto=format&fit=crop&w=800&q=85'); } .gallery-grid div:nth-child(5) { background-image:url('https://images.unsplash.com/photo-1580582932707-520aed937b7b?auto=format&fit=crop&w=800&q=85'); }
        footer { padding:64px 6vw 26px; color:rgba(255,255,255,.78); background:#173b67; } .footer-main { display:flex; justify-content:space-between; gap:35px; padding-bottom:55px; } footer .brand { color:var(--white); } footer p { max-width:280px; font-size:13px; line-height:1.7; } .footer-links { display:flex; gap:42px; font-size:12px; letter-spacing:.1em; text-transform:uppercase; } .footer-links a:hover { color:#f2cd76; } .copyright { padding-top:18px; border-top:1px solid rgba(255,255,255,.22); font-size:11px; display:flex; justify-content:space-between; }
        @media(max-width:760px) { .topbar { justify-content:center; } .topbar span:first-child,nav a:not(.nav-cta):not(.nav-login) { display:none; } header { padding:20px 5vw; } nav { gap:0; } .hero { min-height:680px; } .hero-content { padding:120px 5vw 80px; } .hero-note { display:none; } section { padding:70px 5vw; } .intro,.values { grid-template-columns:1fr; gap:35px; } .section-heading { display:block; } .section-heading p { margin-top:20px; } .level-grid { grid-template-columns:1fr; } .level { min-height:260px; } .gallery-grid { grid-template-columns:1fr 1fr; grid-template-rows:200px 140px 140px; } .gallery-grid div:first-child { grid-row:span 1; grid-column:span 2; } .footer-main,.copyright { display:block; } .footer-links { margin-top:30px; gap:20px; flex-wrap:wrap; } .copyright span { display:block; margin-top:8px; } }
    </style>
</head>
<body>
    <?php ($siteImages = \App\Http\Controllers\SiteImagesController::all()); ?>
    <div class="topbar"><span><?php echo e($config['lema'] ?? 'Educación integral · Inicial · Primaria · Secundaria'); ?></span><span><?php echo e($config['telefono'] ?? 'Admisiones 2027'); ?></span></div>
    <header><a class="brand" href="#inicio"><span class="crest"><img src="<?php echo e(asset('images/santa-maria-logo.svg')); ?>" alt="Escudo Santa Maria"></span><span><?php echo e($config['nombre_colegio'] ?? 'Colegio Santa Maria'); ?></span></a><nav aria-label="Navegación principal"><?php $__currentLoopData = $menus; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $menu): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?> <?php ($menuUrl = match ($menu->slug) { 'inicio' => route('home'), 'servicios' => route('services'), 'noticias' => route('public.news'), 'contacto' => route('contact'), 'institucional' => route('public.pages'), default => route('public.pages') }); ?><a class="<?php echo e($menu->slug === 'contacto' ? 'nav-cta' : ''); ?>" href="<?php echo e($menuUrl); ?>"><?php echo e($menu->titulo); ?></a><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><a href="<?php echo e(route('pastoral')); ?>">Pastoral</a><a href="<?php echo e(route('auth.login')); ?>" class="nav-login">Iniciar sesión</a></nav></header>
    <main>
        <section class="hero" id="inicio" data-image="<?php echo e(optional($banners->first())->imagen ?: $siteImages['home_hero']); ?>"><div class="hero-content"><div class="eyebrow">Inicial · Primaria · Secundaria</div><h1><?php echo e($config['nombre_colegio'] ?? 'Colegio Santa Maria'); ?></h1><p><?php echo e($config['vision'] ?: 'Una comunidad educativa que forma con fe, valores y excelencia para dejar huella en el corazón y preparar el futuro.'); ?></p><div class="hero-actions"><a class="button button-primary" href="#nosotros">Conoce nuestro colegio <span>↗</span></a><a class="button button-ghost" href="<?php echo e(route('contact')); ?>">Solicita información</a></div></div><div class="hero-note">Educación integral</div></section>
        <section class="intro" id="nosotros"><div class="intro-copy"><div class="section-kicker">Quiénes somos</div><h2>Una comunidad que acompaña cada descubrimiento.</h2><p><?php echo e($config['mision'] ?? 'Somos una familia educativa que cree en el potencial único de cada estudiante.'); ?></p></div><div class="intro-aside"><p>“<?php echo e($config['lema'] ?? 'Educar es despertar la confianza para que cada persona pueda dejar su propia huella.'); ?>”</p><small>La propuesta Santa Maria</small></div></section>
        <section class="levels" id="niveles"><div class="section-heading"><div><div class="section-kicker">Nuestra propuesta</div><h2>Aprender en cada etapa</h2></div><p>Ambientes seguros y experiencias significativas para que nuestros estudiantes exploren, creen y encuentren su voz.</p></div><div class="level-grid"><?php $__currentLoopData = $levels; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $index => $level): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="level"><span class="level-number"><?php echo e(str_pad($index + 1, 2, '0', STR_PAD_LEFT)); ?></span><h3><?php echo e($level->nombre); ?></h3><p><?php echo e($level->descripcion ?: 'Una etapa para crecer, aprender y desarrollar todo su potencial.'); ?></p></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></section>
        <?php if($news->isNotEmpty()): ?><section class="news"><div class="section-heading"><div><div class="section-kicker">Noticias</div><h2>Lo que vivimos</h2></div><a class="news-link" href="<?php echo e(route('public.news')); ?>">Ver todas las noticias ↗</a></div><div class="news-grid"><?php $__currentLoopData = $news; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $article): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><article class="news-card"><small><?php echo e($article->fecha_publicacion ? \Illuminate\Support\Carbon::parse($article->fecha_publicacion)->format('d/m/Y') : 'Actualidad'); ?></small><h3><?php echo e($article->titulo); ?></h3><p><?php echo e($article->resumen ?: \Illuminate\Support\Str::limit(strip_tags($article->contenido), 120)); ?></p><a class="news-link" href="<?php echo e(route('public.news.show', $article->slug)); ?>">Leer noticia ↗</a></article><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></section><?php endif; ?>
        <section class="values"><div class="values-copy"><div class="section-kicker">Lo que nos mueve</div><h2>Una formación que permanece.</h2><p>Más que resultados, buscamos desarrollar personas íntegras. Cada día cultivamos hábitos y vínculos que acompañan a nuestros estudiantes mucho más allá del aula.</p></div><div class="value-list"><div class="value-item"><strong>Respeto</strong><span>Miramos al otro con empatía.</span></div><div class="value-item"><strong>Curiosidad</strong><span>Preguntamos para comprender.</span></div><div class="value-item"><strong>Solidaridad</strong><span>Aprendemos a servir.</span></div><div class="value-item"><strong>Excelencia</strong><span>Damos lo mejor de nosotros.</span></div></div></section>
        <section class="gallery"><div class="section-heading"><div><div class="section-kicker">Vida Santa Maria</div><h2>Donde las ideas cobran vida.</h2></div><p>Una mirada a los espacios y momentos que hacen de nuestra comunidad un lugar para crecer.</p></div><div class="gallery-grid"><div></div><div></div><div></div><div></div><div></div></div></section>
    </main>
    <footer id="contacto"><div class="footer-main"><div><a class="brand" href="#inicio"><span class="crest"><img src="<?php echo e(asset('images/santa-maria-logo.svg')); ?>" alt="Escudo Santa Maria"></span><span><?php echo e($config['nombre_colegio'] ?? 'Colegio Santa Maria'); ?></span></a><p><?php echo e($config['lema'] ?? 'Educación que deja huella.'); ?></p></div><div class="footer-links"><a href="#nosotros">Nosotros</a><a href="<?php echo e(route('services')); ?>">Servicios</a><a href="<?php echo e(route('public.news')); ?>">Noticias</a><a href="<?php echo e(route('public.announcements')); ?>">Comunicados</a><a href="<?php echo e(route('public.documents')); ?>">Documentos</a><a href="<?php echo e(route('public.staff')); ?>">Personal</a><a href="<?php echo e(route('public.galleries')); ?>">Galerías</a><a href="<?php echo e(route('contact')); ?>">Contacto</a></div></div><div class="copyright"><span>© 2026 Colegio Santa Maria</span><span><?php echo e($config['direccion'] ?? 'Tumbes, Perú'); ?></span></div></footer>
